'use strict';
const TierUI=(()=>{
 function badge(tier,label){return `<span class="tier-badge tier-${tier.toLowerCase()}" aria-label="${esc(label)} Tier ${tier}"><small>${esc(label)}</small><b>${tier}</b></span>`}
 function birth(s){const r=LifeTiers.report(s);return `<section class="tier-birth" aria-label="Tier ของชีวิตนี้"><div class="tier-birth-heading"><span class="eyebrow">จุดเริ่มต้นของชีวิตนี้</span><button class="tier-help" data-tier-open>ดูเกณฑ์ F → SS ↗</button></div><div class="tier-pair"><div>${badge(r.species.tier,'เผ่าพันธุ์')}<p>${esc(r.species.strength)}</p></div><div>${badge(r.origin.tier,'ชาติกำเนิด')}<p>${esc(r.origin.name)}</p></div></div><p class="tier-note">พลังเมื่อเติบโตในถิ่นที่เหมาะสม · ชาติกำเนิดดูสิทธิและแรงสนับสนุนในสังคมของเผ่า</p></section>`}
 function compact(s){const r=LifeTiers.report(s);return `<button class="tier-summary" data-tier-open aria-label="ดู Tier เผ่าพันธุ์ ชาติกำเนิด และสถานะปัจจุบัน">${badge(r.species.tier,'เผ่า')}${badge(r.origin.tier,'กำเนิด')}${badge(r.standing.tier,'สถานะตอนนี้')}<span aria-hidden="true">↗</span></button>`}
 function open(s=state){const r=LifeTiers.report(s);modal(`<section class="tier-dialog"><span class="eyebrow">F → E → D → C → B → A → S → SS</span><h2>ต้นทุนชีวิต กับสิ่งที่คุณสร้างต่อ</h2><p class="tier-note">Tier เผ่าคือศักยภาพพื้นฐานเมื่อโตเต็มวัยในถิ่นที่เหมาะ ไม่ใช่กำลังปัจจุบันหรือโอกาสชนะทุกการต่อสู้</p><article>${badge(r.species.tier,'เผ่าพันธุ์')}<h3>${esc(r.species.name)}</h3><p>${esc(r.species.strength)}</p><p class="tier-limit">ข้อจำกัด: ${esc(r.species.limit)}</p><small>ถิ่นพื้นฐาน: ${esc(r.species.habitat)}</small></article><article>${badge(r.origin.tier,'ชาติกำเนิด')}<h3>${esc(r.origin.name)}</h3><p>${esc(r.origin.basis)}</p><p class="tier-limit">พันธะและแรงกดดัน: ${esc(r.origin.burden)}</p><p class="tier-note">${s.socialOrigin?.migrated||s.humanOrigin?.migrated?'เซฟเก่า: ประเมินจากข้อมูลกำเนิดที่ยังเหลือ · ':''}จุดเริ่มต้นคงเดิมแม้ชีวิตเปลี่ยนไป</p></article><article>${badge(r.standing.tier,'สถานะตอนนี้')}<h3>${esc(r.standing.name)}</h3><p>${s.race===0?'เปลี่ยนตามชนชั้นและบทบาทที่ได้รับในชีวิต':'เปลี่ยนตามทรัพยากร สิทธิเข้าถึง และเสียงที่กลุ่มรับฟัง เงินส่วนตัวอย่างเดียวซื้อสถานะนี้ไม่ได้'}</p></article><details class="tier-method"><summary>อ่านเกณฑ์จัดลำดับ</summary><p>เผ่าพันธุ์ใช้กำลังและความทนทาน เวท การเคลื่อนที่ และข้อจำกัดทางร่างหรือถิ่นประกอบกัน F เปราะบางที่สุดในภาพรวม SS มีศักยภาพกระทบพื้นที่ระดับอาณาจักร เผ่าที่มี Tier ต่ำยังพัฒนาวิชา สร้างพันธมิตร หรือชนะด้วยบริบทได้</p><p>มนุษย์ใช้สิทธิและเครือข่ายของตระกูล สามัญชน F · ชาวไร่ E · ช่าง D · พ่อค้า C · อัศวิน/จอมเวท B · ขุนนาง A · ราชสกุลสายรอง/มหาตระกูล S · ผู้ครองแผ่นดิน SS</p><p>สังคมเผ่าอื่นใช้ทรัพยากร 30% สิทธิ 35% เสียงในกลุ่ม 35% ตามความหมายเฉพาะของเผ่านั้น เช่น แหล่งฟัก เขตบิน หรือสิทธิใช้เตา ไม่ใช้ลำดับขุนนางมนุษย์</p><p>คะแนนต่ำกว่า 20 = F · 20–34 = E · 35–49 = D · 50–61 = C · 62–73 = B · 74–84 = A · 85–93 = S · 94–100 = SS ความปลอดภัยกับหน้าที่ดูแยกจาก Tier</p><p>Tier เป็นคำอ่านต้นทุนชีวิต ไม่เพิ่มพลัง ลดความเสี่ยง หรือเปลี่ยนโอกาสสุ่มเกิด มนุษย์ยังมีโอกาส 40%</p></details><details class="tier-catalog"><summary>เปิดทำเนียบ ${RACES.length} เผ่าพันธุ์</summary><div>${LifeTiers.order.slice().reverse().map(t=>`<section><h3>${badge(t,'Tier')}</h3>${RACES.map((_,i)=>({i,...LifeTiers.species(i)})).filter(x=>x.tier===t).map(x=>`<p><b>${esc(x.name)}</b><span>${esc(x.strength)}</span></p>`).join('')}</section>`).join('')}</div></details></section>`)}
 function bind(root=document,s=state){root.querySelectorAll('[data-tier-open]').forEach(b=>b.onclick=()=>open(s))}
 return {badge,birth,compact,open,bind};
})();
